/* Phone-only presentation. Desktop renderers remain the source of desktop markup. */
(function(){
 const media=globalThis.matchMedia?.('(max-width: 680px)');
 const phone=()=>globalThis.matchMedia?.('(max-width: 680px)').matches===true;
 const originalNav=merchantNav,originalOrders=bookingSections,originalRender=renderMerchant;
 let orderFilter='upcoming',firstPhoneVisit=true;
 const weekday=d=>['周日','周一','周二','周三','周四','周五','周六'][new Date(d+'T12:00:00+08:00').getUTCDay()];
 const staffName=b=>db.staffSchedule?.staff?.find(s=>s.id===b.staffId)?.name||'待分配';
 const active=b=>SalonCore.active.includes(b.status);
 function appointmentCard(b,next=false,showDate=false){return `<button type="button" class="phone-appointment${next?' phone-next':''}" data-phone-detail="${esc(b.id)}" aria-label="查看${esc(b.name||'未填写客户')}的预约详情"><span class="phone-appointment-time">${showDate?`<small>${b.day.slice(5)} ${weekday(b.day)}</small>`:''}<strong>${time(b.start)}</strong><small>至 ${time(b.start+Number(b.duration))}</small></span><span class="phone-appointment-body">${next?'<small class="phone-next-label">接下来关注</small>':''}<b>${esc(b.name||'未填写客户')}</b><span>${esc(b.title||'理发服务')} · ${b.duration}分钟</span><small>${esc(staffName(b))} · ${stateLabel[b.status]||esc(b.status)}</small></span><span class="phone-detail-arrow" aria-hidden="true">›</span></button>`;}
 function addButton(d){const s=daySchedule(d),start=Math.max(s.open,d===today()?s.open+Math.ceil((currentMinute()-s.open+1)/SalonCore.slotInterval(db))*SalonCore.slotInterval(db):s.open);let available=null;if(d>=today())for(let m=start;m+25<=s.close;m+=SalonCore.slotInterval(db)){if(SalonCore.availableStaff(db,d,m,25).length){available=m;break;}}
  return available===null?'<button type="button" class="phone-add-booking" data-action="merchant-panel" data-value="calendar">查看日程</button>':`<button type="button" class="phone-add-booking" data-action="calendar-empty" data-day="${d}" data-start="${available}">＋ 新增预约</button>`;
 }
 merchantNav=function(){if(!phone())return originalNav();const main=['calendar','orders','assistant'],more=!main.includes(merchantPanel);return `<aside class="workspace-sidebar phone-merchant-sidebar"><div class="side-brand"><span class="side-mark">管理</span><b>店主工作台</b><small>手机工作台</small></div><nav class="phone-bottom-nav" aria-label="商家主要功能">${[['calendar','日程'],['orders','预约'],['assistant','对话']].map(([value,label])=>`<button type="button" data-action="merchant-panel" data-value="${value}" class="${merchantPanel===value?'active':''}"${merchantPanel===value?' aria-current="page"':''}>${label}${value==='orders'?merchantBookingBadge():''}</button>`).join('')}<button type="button" data-phone-more class="${more?'active':''}" aria-haspopup="dialog">更多</button></nav></aside>`;};
 bookingSections=function(){if(!phone())return originalOrders();const all=db.bookings.filter(b=>b.status!=='draft'),items=all.filter(b=>orderFilter==='upcoming'?(active(b)||b.status==='requested'):orderFilter==='week'?b.day>=today()&&b.day<=addDay(today(),6):true).sort((a,b)=>orderFilter==='all'?(Number(b.created)||0)-(Number(a.created)||0)||b.day.localeCompare(a.day):a.day.localeCompare(b.day)||a.start-b.start);return `<section class="phone-orders"><div class="view-title"><h1>预约记录</h1></div><div class="phone-view-tabs phone-order-tabs" aria-label="筛选预约">${[['upcoming','待服务'],['week','近七天'],['all','全部记录']].map(([v,l])=>`<button type="button" data-phone-order="${v}" aria-pressed="${orderFilter===v}">${l}</button>`).join('')}</div><p class="muted">共 ${items.length} 笔 · 点击预约查看详情</p><div class="phone-appointment-list">${items.map(b=>appointmentCard(b,false,true)).join('')||'<div class="card empty">当前没有这类预约。</div>'}</div>${addButton(today())}</section>`;};
 renderMerchant=function(){if(phone()&&firstPhoneVisit){firstPhoneVisit=false;if(merchantPanel==='assistant')merchantPanel='calendar';}return originalRender();};
 function sheet(title,body,kind){document.querySelector('.phone-sheet-backdrop')?.remove();const wrap=document.createElement('div');wrap.className='modal-backdrop phone-sheet-backdrop';wrap.innerHTML=`<section class="profile-modal phone-sheet ${kind||''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="phone-sheet-head"><h2>${esc(title)}</h2><button type="button" class="secondary" data-phone-close>关闭</button></div>${body}</section>`;const close=()=>{wrap.remove();document.removeEventListener('keydown',onKey);},onKey=e=>{if(e.key==='Escape')close();};wrap._phoneClose=close;wrap.onclick=e=>{if(e.target===wrap||e.target.closest('[data-phone-close]'))close();};document.body.appendChild(wrap);document.addEventListener('keydown',onKey);wrap.querySelector('[data-phone-close]').focus();return wrap;}
 function detailsHTML(b){return `<div class="phone-detail-status"><span class="badge">${stateLabel[b.status]||esc(b.status)}</span><h3>${esc(b.name||'未填写客户')}</h3></div><dl class="phone-booking-facts"><div><dt>项目</dt><dd>${esc(b.title||'理发服务')}${b.hair==='short'?' · 短发':b.hair==='long'?' · 长发':''}</dd></div><div><dt>日期</dt><dd>${b.day} ${weekday(b.day)}</dd></div><div><dt>服务时间</dt><dd>${time(b.start)}–${time(b.start+Number(b.duration))} · ${b.duration}分钟</dd></div><div><dt>理发师</dt><dd>${esc(staffName(b))}</dd></div><div><dt>联系电话</dt><dd>${bookingContactLink(b)}</dd></div>${b.notes?`<div class="phone-note"><dt>备注</dt><dd>${esc(b.notes)}</dd></div>`:''}</dl><div class="phone-detail-actions">${active(b)?`<button type="button" class="secondary" data-phone-edit="${esc(b.id)}">修改预约信息</button>`:''}${lifecycleButtons(b)}</div>`;}
 function openDetails(id){const b=db.bookings.find(b=>b.id===id);if(b)sheet('预约详情',detailsHTML(b),'phone-booking-detail');}
 document.addEventListener('click',e=>{if(!phone()||view!=='merchant')return;const b=e.target.closest('[data-phone-more],[data-phone-panel],[data-phone-order],[data-phone-detail],[data-phone-edit]');if(!b)return;e.preventDefault();
  if(b.hasAttribute('data-phone-more')){sheet('更多功能',`<div class="phone-more-options">${[['customers','顾客资料','查找客户、查看服务记录'],['reports','每周记录与总结','查看每日明细与每周统计'],['settings','门店设置','调整营业时间、排班和护理提醒'],['guide','操作流程','查看预约、接待和分享入口的步骤']].map(([v,title,note])=>`<button type="button" data-phone-panel="${v}"><b>${title}</b><small>${note}</small></button>`).join('')}</div>`);return;}
  if(b.dataset.phonePanel){merchantPanel=b.dataset.phonePanel;document.querySelector('.phone-sheet-backdrop')?._phoneClose();render();return;}
  if(b.dataset.phoneOrder){orderFilter=b.dataset.phoneOrder;render();return;}
  if(b.dataset.phoneDetail){openDetails(b.dataset.phoneDetail);return;}
  if(b.dataset.phoneEdit){document.querySelector('.phone-sheet-backdrop')?._phoneClose();openBookingEditor(b.dataset.phoneEdit,false);}
 });
 document.addEventListener('click',e=>{if(!phone())return;const action=e.target.closest('[data-action="progress-book"],[data-action="cancel-book"],[data-action="reject"]'),wrap=action?.closest('.phone-sheet-backdrop');if(wrap){const record=db.bookings.find(b=>b.id===action.dataset.id);if(record&&(record.status==='cancelled'||record.status===action.dataset.next))wrap._phoneClose();}});
 media?.addEventListener?.('change',()=>{if(!document.querySelector('.modal-backdrop'))render();});
 window.SalonPhone={isPhone:phone,detailsHTML,appointmentCard};
 if(phone())render();
})();
